	Page<Map<String, Object>> getByExpenseManagmentId(@Param("btExpenseManagmentId")long btExpenseManagmentId,Pageable page);
	
	
	@Query(value ="SELECT lce.id, lce.manual_id as manualId,lce.date as date, em.id as btExpenseManagementId,em.manual_id as btExpenseManagementManualId,bd.business_domain_id AS businessDomainId, bd.business_domain_name AS businessDomainName,lce.mode_of_travel_id AS modeOfTravelId,mt.name AS modeOfTravelName,lce.own_conveyance_id AS ownConveyanceId,oc.name AS ownConveyanceName,lce.from_place AS fromPlace,lce.to_place AS toPlace,lce.amount,lce.distance,lce.remark,lce.created_by_email_id AS createdByEmailId,CONCAT(IFNULL(ed.`first_name`,' '),IFNULL(ed.`middle_name`,' '),IFNULL(ed.`last_name`,''))AS `createdByName`,lce.created_date AS createdDate,lce.last_modified_by_email_id AS lastModifiedByEmailId,CONCAT(IFNULL(ed.`first_name`,' '),IFNULL(ed.`middle_name`,' '),IFNULL(ed.`last_name`,''))AS `modifiedByName`,lce.last_modified_date AS lastModifiedDate,lce.owner_email_id AS ownerEmailId,CONCAT(IFNULL(ed.`first_name`,' '),IFNULL(ed.`middle_name`,' '),IFNULL(ed.`last_name`,''))AS `ownerByName`,lce.amount_to_disbursed AS amountToDisbursed FROM bt_local_conveyance_expense lce LEFT JOIN bt_expense_management em ON lce.bt_expense_management_id=em.id LEFT JOIN own_conveyance  oc ON oc.id=lce.own_conveyance_id  LEFT JOIN mode_of_travel mt ON mt.id=lce.mode_of_travel_id LEFT JOIN employee_details ed ON lce.created_by_email_Id=ed.email_id LEFT JOIN business_domain bd ON bd.business_domain_id=em.business_domain_business_domain_id where lce.is_deleted=false and em.id=:btExpenseManagmentId",nativeQuery = true)
	List<Map<String, Object>> getListByExpenseManagmentId(@Param("btExpenseManagmentId")long btExpenseManagmentId);
